@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root{
  --bg-primary:oklch(13% 0.02 240);
  --bg-secondary:oklch(17% 0.02 240);
  --bg-card:oklch(19% 0.02 240);
  --bg-card-hover:oklch(22% 0.02 240);
  --bg-code:oklch(15% 0.015 240);
  --border:oklch(28% 0.015 240);
  --border-hover:oklch(35% 0.02 240);
  --text-primary:oklch(93% 0.005 240);
  --text-secondary:oklch(65% 0.01 240);
  --text-tertiary:oklch(50% 0.01 240);
  --accent-green:oklch(72% 0.19 155);
  --accent-green-dim:oklch(72% 0.19 155 / 0.12);
  --accent-cyan:oklch(72% 0.11 230);
  --accent-cyan-dim:oklch(72% 0.11 230 / 0.12);
  --accent-purple:oklch(68% 0.16 300);
  --accent-purple-dim:oklch(68% 0.16 300 / 0.12);
  --accent-orange:oklch(72% 0.15 55);
  --accent-orange-dim:oklch(72% 0.15 55 / 0.12);
  --font-sans:'Inter',system-ui,-apple-system,sans-serif;
  --font-mono:'JetBrains Mono','Fira Code',monospace;
  --radius-sm:6px;
  --radius-md:10px;
  --radius-lg:14px;
  --radius-xl:20px;
  --transition:180ms ease;
  --transition-slow:300ms ease;
  --max-width:1280px;
  --sidebar-width:260px;
  --nav-height:60px;
}

html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font-sans);background:var(--bg-primary);color:var(--text-primary);line-height:1.6;font-size:15px;min-height:100vh;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}
img,svg{display:block;max-width:100%}
code,pre{font-family:var(--font-mono)}

/* ── Top Navigation ────────────────────────── */
.top-nav{position:sticky;top:0;z-index:100;background:oklch(13% 0.02 240 / 0.85);backdrop-filter:blur(16px) saturate(180%);-webkit-backdrop-filter:blur(16px) saturate(180%);border-bottom:1px solid var(--border);height:var(--nav-height)}
.nav-container{max-width:var(--max-width);margin:0 auto;padding:0 24px;display:flex;align-items:center;height:100%;gap:32px}
.nav-logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:16px;letter-spacing:-0.02em;white-space:nowrap;color:var(--text-primary)}
.nav-logo svg{width:24px;height:24px;flex-shrink:0}
.nav-links{display:flex;gap:4px;flex:1}
.nav-links a{padding:8px 14px;border-radius:var(--radius-sm);font-size:14px;font-weight:500;color:var(--text-secondary);transition:color var(--transition),background var(--transition)}
.nav-links a:hover,.nav-links a.active{color:var(--text-primary);background:oklch(100% 0 0 / 0.06)}
.nav-actions{display:flex;align-items:center;gap:12px}
.search-btn{display:flex;align-items:center;gap:8px;padding:6px 14px;border-radius:var(--radius-sm);border:1px solid var(--border);color:var(--text-tertiary);font-size:13px;transition:border-color var(--transition),color var(--transition)}
.search-btn:hover{border-color:var(--border-hover);color:var(--text-secondary)}
.search-btn svg{width:15px;height:15px}
.search-btn kbd{font-family:var(--font-sans);font-size:11px;padding:2px 6px;border-radius:4px;border:1px solid var(--border);background:var(--bg-secondary);margin-left:16px}
.nav-login{font-size:14px;font-weight:500;color:var(--text-secondary);padding:6px 16px;border-radius:var(--radius-sm);border:1px solid var(--border);transition:all var(--transition)}
.nav-login:hover{color:var(--text-primary);border-color:var(--border-hover);background:oklch(100% 0 0 / 0.04)}
.mobile-menu-btn{display:none;padding:8px;border-radius:var(--radius-sm)}
.mobile-menu-btn svg{width:22px;height:22px}

/* ── Mobile Navigation ────────────────────── */
.mobile-nav{display:none;position:fixed;top:var(--nav-height);left:0;right:0;bottom:0;background:var(--bg-primary);z-index:99;padding:16px 24px;flex-direction:column;gap:4px;border-top:1px solid var(--border)}
.mobile-nav.open{display:flex}
.mobile-nav a{padding:12px 16px;border-radius:var(--radius-sm);font-size:16px;font-weight:500;color:var(--text-secondary);transition:background var(--transition)}
.mobile-nav a:hover{background:var(--bg-secondary);color:var(--text-primary)}

/* ── Hero Sections ─────────────────────────── */
.hero{padding:80px 24px 64px;text-align:center}
.hero-inner{max-width:800px;margin:0 auto}
.hero-badge{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border-radius:999px;font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:20px;border:1px solid}
.hero-badge.green{color:var(--accent-green);border-color:oklch(72% 0.19 155 / 0.3);background:var(--accent-green-dim)}
.hero-badge.cyan{color:var(--accent-cyan);border-color:oklch(72% 0.11 230 / 0.3);background:var(--accent-cyan-dim)}
.hero-badge.purple{color:var(--accent-purple);border-color:oklch(68% 0.16 300 / 0.3);background:var(--accent-purple-dim)}
.hero h1{font-size:clamp(32px,5vw,52px);font-weight:800;line-height:1.1;letter-spacing:-0.03em;margin-bottom:16px}
.hero p{font-size:clamp(16px,2vw,18px);color:var(--text-secondary);max-width:640px;margin:0 auto 32px;line-height:1.7}
.hero-actions{display:flex;flex-wrap:wrap;gap:12px;justify-content:center}

/* ── Buttons ───────────────────────────────── */
.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 20px;border-radius:var(--radius-sm);font-size:14px;font-weight:600;transition:all var(--transition);white-space:nowrap}
.btn-primary{background:var(--accent-green);color:oklch(15% 0.04 155)}
.btn-primary:hover{background:oklch(76% 0.19 155);transform:translateY(-1px)}
.btn-secondary{border:1px solid var(--border);color:var(--text-primary);background:transparent}
.btn-secondary:hover{border-color:var(--border-hover);background:oklch(100% 0 0 / 0.04)}
.btn-cyan{background:var(--accent-cyan);color:oklch(15% 0.04 230)}
.btn-cyan:hover{background:oklch(76% 0.12 230);transform:translateY(-1px)}
.btn-purple{background:var(--accent-purple);color:oklch(15% 0.04 300)}
.btn-purple:hover{background:oklch(72% 0.16 300);transform:translateY(-1px)}
.btn-ghost{color:var(--accent-green);padding:10px 4px}
.btn-ghost:hover{color:oklch(78% 0.19 155)}
.btn-ghost svg{width:16px;height:16px;transition:transform var(--transition)}
.btn-ghost:hover svg{transform:translateX(3px)}

/* ── Section Layout ────────────────────────── */
.section{padding:64px 24px}
.section-inner{max-width:var(--max-width);margin:0 auto}
.section-header{margin-bottom:48px}
.section-header.center{text-align:center}
.section-label{font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.06em;color:var(--accent-green);margin-bottom:12px}
.section-header h2{font-size:clamp(24px,3.5vw,36px);font-weight:700;letter-spacing:-0.025em;line-height:1.2;margin-bottom:12px}
.section-header p{font-size:16px;color:var(--text-secondary);max-width:600px;line-height:1.7}
.section-header.center p{margin:0 auto}
.section-divider{border:none;border-top:1px solid var(--border);max-width:var(--max-width);margin:0 auto}

/* ── Card Components ───────────────────────── */
.card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:28px;transition:all var(--transition)}
.card:hover{border-color:var(--border-hover);background:var(--bg-card-hover);transform:translateY(-2px);box-shadow:0 8px 32px oklch(0% 0 0 / 0.2)}
.card-icon{width:44px;height:44px;border-radius:var(--radius-md);display:flex;align-items:center;justify-content:center;margin-bottom:16px;font-size:20px}
.card-icon.green{background:var(--accent-green-dim);color:var(--accent-green)}
.card-icon.cyan{background:var(--accent-cyan-dim);color:var(--accent-cyan)}
.card-icon.purple{background:var(--accent-purple-dim);color:var(--accent-purple)}
.card-icon.orange{background:var(--accent-orange-dim);color:var(--accent-orange)}
.card h3{font-size:17px;font-weight:600;margin-bottom:8px;letter-spacing:-0.01em}
.card p{font-size:14px;color:var(--text-secondary);line-height:1.65}
.card .card-link{display:inline-flex;align-items:center;gap:6px;margin-top:16px;font-size:13px;font-weight:600;color:var(--accent-green);transition:color var(--transition)}
.card .card-link:hover{color:oklch(78% 0.19 155)}
.card .card-link svg{width:14px;height:14px;transition:transform var(--transition)}
.card .card-link:hover svg{transform:translateX(3px)}

/* ── Product Cards (Home) ──────────────────── */
.product-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.product-card{position:relative;overflow:hidden;padding:32px}
.product-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px}
.product-card.apps::before{background:linear-gradient(90deg,var(--accent-green),oklch(72% 0.15 180))}
.product-card.storefronts::before{background:linear-gradient(90deg,var(--accent-cyan),oklch(72% 0.12 260))}
.product-card.agents::before{background:linear-gradient(90deg,var(--accent-purple),oklch(68% 0.14 330))}
.product-card h3{font-size:20px;font-weight:700;margin-bottom:10px}

/* ── Grids ─────────────────────────────────── */
.grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}

/* ── CLI Setup Section ─────────────────────── */
.cli-section{background:var(--bg-secondary);border-top:1px solid var(--border);border-bottom:1px solid var(--border)}

.accordion-item{border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;transition:border-color var(--transition);margin-bottom:12px}
.accordion-item:hover{border-color:var(--border-hover)}
.accordion-item.active{border-color:var(--accent-green)}
.accordion-header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;cursor:pointer;font-weight:600;font-size:15px;background:var(--bg-card);transition:background var(--transition)}
.accordion-header:hover{background:var(--bg-card-hover)}
.accordion-header .chevron{width:20px;height:20px;transition:transform var(--transition-slow);color:var(--text-tertiary)}
.accordion-item.active .accordion-header .chevron{transform:rotate(180deg);color:var(--accent-green)}
.accordion-header .step-label{display:flex;align-items:center;gap:10px}
.accordion-header .step-num{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;background:var(--border);color:var(--text-secondary);transition:all var(--transition)}
.accordion-item.active .accordion-header .step-num{background:var(--accent-green);color:oklch(15% 0.04 155)}
.accordion-body{max-height:0;overflow:hidden;transition:max-height var(--transition-slow) ease}
.accordion-item.active .accordion-body{max-height:600px}
.accordion-content{padding:20px 24px 24px;border-top:1px solid var(--border)}

.cli-steps{display:flex;flex-direction:column;gap:14px;margin-bottom:20px}
.cli-step{display:flex;gap:12px;font-size:14px;color:var(--text-secondary);line-height:1.6}
.cli-step .num{flex-shrink:0;width:22px;height:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;background:oklch(100% 0 0 / 0.06);color:var(--text-tertiary);margin-top:2px}

/* ── Tabs ──────────────────────────────────── */
.tab-group{border:1px solid var(--border);border-radius:var(--radius-md);overflow:hidden;background:var(--bg-code)}
.tab-bar{display:flex;border-bottom:1px solid var(--border);background:oklch(16% 0.015 240)}
.tab-btn{padding:8px 18px;font-size:13px;font-weight:500;color:var(--text-tertiary);position:relative;transition:color var(--transition)}
.tab-btn:hover{color:var(--text-secondary)}
.tab-btn.active{color:var(--accent-green)}
.tab-btn.active::after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:var(--accent-green)}
.tab-panel{display:none;padding:16px 20px}
.tab-panel.active{display:block}
.tab-panel code{font-size:13px;color:var(--accent-green);line-height:1.8}
.tab-panel .comment{color:var(--text-tertiary)}

.code-block{background:var(--bg-code);border:1px solid var(--border);border-radius:var(--radius-md);padding:16px 20px;margin-top:12px}
.code-block code{font-size:13px;color:var(--accent-cyan);display:block;line-height:1.8}

/* ── Launch CTA Cards ──────────────────────── */
.launch-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}
.launch-card{padding:32px;display:flex;flex-direction:column;gap:12px;background:linear-gradient(135deg,var(--bg-card),oklch(20% 0.03 240))}
.launch-card h3{font-size:20px;font-weight:700}
.launch-card p{flex:1}

/* ── Community Resources ───────────────────── */
.community-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.community-card{padding:24px;display:flex;flex-direction:column;gap:8px}
.community-card h3{font-size:15px;font-weight:600;display:flex;align-items:center;gap:6px}
.community-card h3 svg{width:16px;height:16px;color:var(--text-tertiary)}

/* ── Sidebar Layout ────────────────────────── */
.docs-layout{display:flex;min-height:calc(100vh - var(--nav-height))}
.sidebar{width:var(--sidebar-width);flex-shrink:0;border-right:1px solid var(--border);background:var(--bg-secondary);padding:24px 0;overflow-y:auto;transition:width var(--transition-slow),padding var(--transition-slow);position:sticky;top:var(--nav-height);height:calc(100vh - var(--nav-height))}
.sidebar.collapsed{width:0;padding:0;overflow:hidden}
.sidebar-header{display:flex;align-items:center;justify-content:space-between;padding:0 20px 16px;border-bottom:1px solid var(--border);margin-bottom:12px}
.sidebar-header h3{font-size:14px;font-weight:700;letter-spacing:-0.01em}
.sidebar-toggle{padding:6px;border-radius:var(--radius-sm);transition:background var(--transition);display:flex;align-items:center;justify-content:center}
.sidebar-toggle:hover{background:oklch(100% 0 0 / 0.08)}
.sidebar-toggle svg{width:18px;height:18px}
.sidebar-nav{padding:0 12px}
.sidebar-nav-group{margin-bottom:16px}
.sidebar-nav-group-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.07em;color:var(--text-tertiary);padding:8px;margin-bottom:2px}
.sidebar-nav a{display:block;padding:7px 12px;border-radius:var(--radius-sm);font-size:13px;color:var(--text-secondary);transition:all var(--transition)}
.sidebar-nav a:hover{background:oklch(100% 0 0 / 0.05);color:var(--text-primary)}
.sidebar-nav a.active{background:var(--accent-green-dim);color:var(--accent-green);font-weight:500}
.docs-content{flex:1;min-width:0;padding:40px 48px 80px}
.docs-content .section{padding:0 0 48px}
.docs-content .section+.section{padding-top:48px;border-top:1px solid var(--border)}

.expand-sidebar-btn{position:fixed;left:8px;top:calc(var(--nav-height) + 12px);z-index:50;padding:8px;border-radius:var(--radius-sm);background:var(--bg-secondary);border:1px solid var(--border);display:none;transition:all var(--transition)}
.expand-sidebar-btn:hover{background:var(--bg-card);border-color:var(--border-hover)}
.expand-sidebar-btn svg{width:18px;height:18px}
.sidebar.collapsed~.docs-content .expand-sidebar-btn,
.sidebar.collapsed~.expand-sidebar-btn{display:flex}

/* ── Protocol Diagram ──────────────────────── */
.protocol-actors{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.actor-card{text-align:center;padding:28px 20px}
.actor-icon{width:56px;height:56px;border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 14px;font-size:20px;font-weight:700;border:2px solid}
.actor-icon.agent{border-color:var(--accent-green);color:var(--accent-green);background:var(--accent-green-dim)}
.actor-icon.merchant{border-color:var(--accent-cyan);color:var(--accent-cyan);background:var(--accent-cyan-dim)}
.actor-icon.cp{border-color:var(--accent-orange);color:var(--accent-orange);background:var(--accent-orange-dim)}
.actor-icon.psp{border-color:var(--accent-purple);color:var(--accent-purple);background:var(--accent-purple-dim)}
.actor-card h3{font-size:15px;margin-bottom:6px}

/* ── How It Works ──────────────────────────── */
.flow-cards{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}
.flow-card{padding:28px;position:relative;overflow:hidden}
.flow-card .flow-num{position:absolute;top:16px;right:20px;font-size:48px;font-weight:800;color:oklch(100% 0 0 / 0.04);line-height:1}
.flow-card h3{font-size:18px;margin-bottom:10px}
.flow-badge{display:inline-block;padding:4px 10px;border-radius:999px;font-size:11px;font-weight:600;background:var(--accent-orange-dim);color:var(--accent-orange);margin-top:12px}

/* ── Support Categories ────────────────────── */
.support-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.support-card{padding:28px;display:flex;flex-direction:column;gap:8px}
.support-card h3{font-size:17px;font-weight:600}
.support-card .tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px}
.support-card .tag{padding:4px 10px;border-radius:999px;font-size:12px;background:oklch(100% 0 0 / 0.05);color:var(--text-secondary);border:1px solid var(--border)}

/* ── Footer ────────────────────────────────── */
.footer{border-top:1px solid var(--border);padding:56px 24px 32px;background:var(--bg-secondary)}
.footer-inner{max-width:var(--max-width);margin:0 auto}
.footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:40px;margin-bottom:48px}
.footer-col h4{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-tertiary);margin-bottom:14px}
.footer-col a{display:block;font-size:13px;color:var(--text-secondary);padding:4px 0;transition:color var(--transition)}
.footer-col a:hover{color:var(--text-primary)}
.footer-bottom{display:flex;justify-content:space-between;align-items:center;padding-top:24px;border-top:1px solid var(--border);font-size:13px;color:var(--text-tertiary)}

/* ── Utility ───────────────────────────────── */
.glass{background:oklch(19% 0.02 240 / 0.6);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.gradient-text{background:linear-gradient(135deg,var(--accent-green),var(--accent-cyan));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}

/* ── Responsive ────────────────────────────── */
@media(max-width:1024px){
  .product-cards{grid-template-columns:1fr}
  .grid-4,.community-grid{grid-template-columns:repeat(2,1fr)}
  .protocol-actors{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:repeat(2,1fr);gap:32px}
  .docs-content{padding:32px 28px 64px}
  .sidebar{width:220px}
}
@media(max-width:768px){
  .nav-links,.nav-actions{display:none}
  .mobile-menu-btn{display:flex}
  .hero{padding:56px 20px 48px}
  .section{padding:48px 20px}
  .product-cards,.grid-2,.grid-3,.launch-grid,.flow-cards,.support-grid{grid-template-columns:1fr}
  .grid-4,.community-grid{grid-template-columns:1fr}
  .protocol-actors{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:1fr;gap:28px}
  .sidebar{position:fixed;left:0;top:var(--nav-height);z-index:90;width:280px;transform:translateX(0);box-shadow:4px 0 24px oklch(0% 0 0 / 0.3)}
  .sidebar.collapsed{transform:translateX(-100%);width:280px}
  .docs-content{padding:24px 20px 64px}
  .hero-actions{flex-direction:column;align-items:stretch}
  .hero-actions .btn{justify-content:center}
  .search-btn kbd{display:none}
}
@media(max-width:480px){
  .protocol-actors{grid-template-columns:1fr}
  .tab-btn{padding:8px 12px;font-size:12px}
}

